function box(g,w,h,d,x,y,z,c,metal=0){const m=new T.Mesh(new T.BoxGeometry(w,h,d),typeof c==='object'?c:material(c,metal));m.position.set(x,y,z);m.castShadow=true;m.receiveShadow=true;g.add(m);return m}
